from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def sort_list(head: list[int]) -> list[int]:
    class Node:
        def __init__(self, value: int, nxt=None):
            self.value = value
            self.nxt = nxt

    def build(values: list[int]):
        dummy = Node(0)
        tail = dummy
        for value in values:
            tail.nxt = Node(value)
            tail = tail.nxt
        return dummy.nxt

    def merge(a, b):
        dummy = Node(0)
        tail = dummy
        while a and b:
            if a.value <= b.value:
                tail.nxt, a = a, a.nxt
            else:
                tail.nxt, b = b, b.nxt
            tail = tail.nxt
        tail.nxt = a or b
        return dummy.nxt

    def merge_sort(node):
        if node is None or node.nxt is None:
            return node
        slow, fast = node, node.nxt
        while fast and fast.nxt:
            slow = slow.nxt
            fast = fast.nxt.nxt
        mid = slow.nxt
        slow.nxt = None
        return merge(merge_sort(node), merge_sort(mid))

    node = merge_sort(build(head))
    out = []
    while node:
        out.append(node.value)
        node = node.nxt
    return out

